💡 Topics they asked me & my solutions:
** Note: This is exactly the answers that I provided during the interview. **
✅ What is a closure?
const counter = () => {
    let count = 0;

    const inner = () => {
        count++;
        return count
    }

    count = 2;

    return inner;
}

const c = counter();

console.log(c()); // 3

✅ Predict setTimeout output
for (var i = 0; i < 3; i++) {
    setTimeout(function log() {
        console.log(i);
    }, 1000);
}

✅ Implement currying for sum
const sum = (arg) => {
    let total = 0;

    const inner = (n) => {
        if (n) {
            total += n;
            return inner;
        } else {
            return total;
        }
    };

    if (arg) {
        total += arg;
    }
    return inner;
};

